 private void beam(Player p,int length,double width,double damage,CombatDamageService.DamageKind kind,Consumer<LivingEntity> effect){Set<UUID> seen=new HashSet<>();Location start=p.getEyeLocation();Vector direction=direction(p);for(double d=1;d<=length;d+=.8){Location at=start.clone().add(direction.clone().multiply(d));if(at.getBlock().getType().isSolid())break;at.getWorld().spawnParticle(Particle.END_ROD,at,4,.2,.2,.2,0);for(var e:enemies(p,at,width/2))if(seen.add(e.getUniqueId())&&r.damage().scaledHit(p,e,damage,kind)>0)effect.accept(e);}}
 private int stacks(Map<TargetKey,Stack> map,Player p,LivingEntity e){Stack s=map.get(new TargetKey(p.getUniqueId(),e.getUniqueId()));return s!=null&&s.until>now()?s.count:0;}private void stack(Map<TargetKey,Stack> map,Player p,LivingEntity e,int n,int max,double seconds){map.put(new TargetKey(p.getUniqueId(),e.getUniqueId()),new Stack(Math.min(max,stacks(map,p,e)+n),now()+(long)(seconds*1000)));if(map==shadow)r.vfx().mark(p,e,stacks(map,p,e));}
